using System;using System.Data;using System.Data.SqlClient;using System.Text;using System.Web;namespace schoolms{public partial class student_Schedule:System.Web.UI.Page{protected void Page_Load(object s,EventArgs e){string enrl=Session["Stud"] as string;if(enrl==null){Response.Redirect("Student_Login.aspx");return;}if(!IsPostBack)Load(enrl);}void Load(string enrl){try{using(SqlConnection c=Db.CreateConnection()){c.Open();int cls=1;using(SqlCommand q=new SqlCommand("SELECT ISNULL(ClassNo,1) FROM Stud WHERE EnrlNo=@E",c)){q.Parameters.Add("@E",SqlDbType.NVarChar,30).Value=enrl;object x=q.ExecuteScalar();if(x!=null&&x!=DBNull.Value)cls=Convert.ToInt32(x);}DataTable t=new DataTable();using(SqlDataAdapter d=new SqlDataAdapter("SELECT TimeSlot,Subject,IsBreak FROM ClassTimetable WHERE ClassNo=@C ORDER BY SortOrder",c)){d.SelectCommand.Parameters.Add("@C",SqlDbType.Int).Value=cls;d.Fill(t);}StringBuilder b=new StringBuilder("<h2>Class "+cls+" Timetable</h2><table><tr><th>Time</th><th>Subject</th></tr>");foreach(DataRow r in t.Rows)b.Append("<tr><td>").Append(HttpUtility.HtmlEncode(Convert.ToString(r["TimeSlot"]))).Append("</td><td>").Append(HttpUtility.HtmlEncode(Convert.ToString(r["Subject"]))).Append(Convert.ToBoolean(r["IsBreak"])?" (Break)":"").Append("</td></tr>");b.Append("</table>");litSchedule.Text=b.ToString();}}catch(SqlException){litSchedule.Text="<p>Could not load the timetable.</p>";}}}}
